item.aggregated_output:
                    require_value(args, index, "--exit-after-modules <EXIT_AFTER_MODULES>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.exit_after_modules = Some(parse_exit_after_modules(value)?);
                index += 2;
            }
            "--print-completions" => {
                let value = require_value(args, index, "--print-completions <shell>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.print_completions =
                    Some(CompletionShell::parse(value).ok_or_else(|| {
                        invalid_enum_value(
                            value,
                            "--print-completions <shell>",
                            &SHELL_VALUES,
                            None,
                        )
                    })?);
                index += 2;
            }
            "--print-manpage" => {
                parsed.print_manpage = true;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--modules=") => {
                let module = Module::parse(value).ok_or_else(|| {
                    invalid_enum_value(
                        value,
                        "--modules <MODULES>",
                        &MODULE_VALUES,
                        best_suggestion(value, &MODULE_VALUES),
                    )
                })?;
                parsed.modules.push(module);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--speed-factor=") => {
                parsed.speed_factor = parse_speed_factor(value)?;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--instant-print-lines=") => {
                parsed.instant_print_lines = value.parse::<usize>().map_err(|err| {
                    invalid_value_message(
                        value,
                        "--instant-print-lines <INSTANT_PRINT_LINES>",
                        &err.to_string(),
                    )
                })?;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--exit-after-time=") => {
                parsed.exit_after_time = Some(parse_duration_flag(value)?);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--exit-after-modules=") => {
                parsed.exit_after_modules = Some(parse_exit_after_modules(value)?);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--print-completions=") => {
                parsed.print_completions =
                    Some(CompletionShell::parse(value).ok_or_else(|| {
                        invalid_enum_value(
                            value,
                            "--print-completions <shell>",
                            &SHELL_VALUES,
                            None,
                        )
                    })?);
                index += 1;
            }
            _ => {
                return Err(unexpected_argument(bin_name, arg));
            }
        }
    }

    Ok(parsed)
}

